use vstd::prelude::*;

verus! {

    #[derive(PartialEq, Eq, Copy, Clone)]
    enum NumpyTypeClass {
        IntegerType,
        FloatingType,
        ComplexType,
        BooleanType,
        ScalarType,
        NumberType,
        InexactType,
        Int8Type,
        Int16Type,
        Int32Type,
        Int64Type,
        UInt8Type,
        UInt16Type,
        UInt32Type,
        UInt64Type,
        Float32Type,
        Float64Type,
        Complex64Type,
        Complex128Type,
        ObjectType,
    }

    /// The specification of the *direct* subclass relation.
    spec fn is_direct_subclass(a: NumpyTypeClass, b: NumpyTypeClass) -> bool {
        // Reflexivity
        a == b
        // Integer leaves
        || ((a == NumpyTypeClass::Int8Type
            || a == NumpyTypeClass::Int16Type
            || a == NumpyTypeClass::Int32Type
            || a == NumpyTypeClass::Int64Type
            || a == NumpyTypeClass::UInt8Type
            || a == NumpyTypeClass::UInt16Type
            || a == NumpyTypeClass::UInt32Type
            || a == NumpyTypeClass::UInt64Type)
            && b == NumpyTypeClass::IntegerType)
        // Floating‐point leaves
        || ((a == NumpyTypeClass::Float32Type
            || a == NumpyTypeClass::Float64Type)
            && b == NumpyTypeClass::FloatingType)
        // Complex leaves
        || ((a == NumpyTypeClass::Complex64Type
            || a == NumpyTypeClass::Complex128Type)
            && b == NumpyTypeClass::ComplexType)
        // Mid‐level relations
        || (a == NumpyTypeClass::IntegerType && b == NumpyTypeClass::NumberType)
        || (a == NumpyTypeClass::FloatingType
            && (b == NumpyTypeClass::InexactType || b == NumpyTypeClass::NumberType))
        || (a == NumpyTypeClass::ComplexType
            && (b == NumpyTypeClass::InexactType || b == NumpyTypeClass::NumberType))
        // Top‐level scalar relations
        || ((a == NumpyTypeClass::NumberType
            || a == NumpyTypeClass::BooleanType
            || a == NumpyTypeClass::IntegerType
            || a == NumpyTypeClass::FloatingType
            || a == NumpyTypeClass::ComplexType
            || a == NumpyTypeClass::InexactType)
            && b == NumpyTypeClass::ScalarType)
        // No other direct‐subclass pairs
    }

    /// Implementation of the direct subclass test, matching the specification above.
    fn issubclass_(a: NumpyTypeClass, b: NumpyTypeClass) -> bool
        ensures
            result == is_direct_subclass(a, b)
    {
        // Reflexivity
        if a == b {
            true
        } else {
            // All other cases
            match a {
                // Integer leaves → IntegerType
                NumpyTypeClass::Int8Type
                | NumpyTypeClass::Int16Type
                | NumpyTypeClass::Int32Type
                | NumpyTypeClass::Int64Type
                | NumpyTypeClass::UInt8Type
                | NumpyTypeClass::UInt16Type
                | NumpyTypeClass::UInt32Type
                | NumpyTypeClass::UInt64Type => {
                    b == NumpyTypeClass::IntegerType
                }

                // Floating‐point leaves → FloatingType
                NumpyTypeClass::Float32Type
                | NumpyTypeClass::Float64Type => {
                    b == NumpyTypeClass::FloatingType
                }

                // Complex leaves → ComplexType
                NumpyTypeClass::Complex64Type
                | NumpyTypeClass::Complex128Type => {
                    b == NumpyTypeClass::ComplexType
                }

                // IntegerType → NumberType and ScalarType
                NumpyTypeClass::IntegerType => {
                    b == NumpyTypeClass::NumberType
                    || b == NumpyTypeClass::ScalarType
                }

                // FloatingType → InexactType, NumberType, ScalarType
                NumpyTypeClass::FloatingType => {
                    b == NumpyTypeClass::InexactType
                    || b == NumpyTypeClass::NumberType
                    || b == NumpyTypeClass::ScalarType
                }

                // ComplexType → InexactType, NumberType, ScalarType
                NumpyTypeClass::ComplexType => {
                    b == NumpyTypeClass::InexactType
                    || b == NumpyTypeClass::NumberType
                    || b == NumpyTypeClass::ScalarType
                }

                // NumberType, BooleanType, InexactType → ScalarType
                NumpyTypeClass::NumberType
                | NumpyTypeClass::BooleanType
                | NumpyTypeClass::InexactType => {
                    b == NumpyTypeClass::ScalarType
                }

                // Everything else (including ObjectType) has no direct subclass relation
                _ => false,
            }
        }
    }
}

fn main() {
    // Examples of usage
    assert!(issubclass_(NumpyTypeClass::Int32Type, NumpyTypeClass::IntegerType));
    assert!(issubclass_(NumpyTypeClass::FloatingType, NumpyTypeClass::ScalarType));
    assert!(!issubclass_(NumpyTypeClass::Int32Type, NumpyTypeClass::NumberType)); // not direct
    assert!(issubclass_(NumpyTypeClass::ObjectType, NumpyTypeClass::ObjectType)); // reflexivity
}